with deduped as (select id, email, manager_id, salary, is_remote from (select *, row_number() over (partition by job_title, dept_id order by hire_date nulls first, id) as row_num from employees) x where row_num = 1), with_windows as (select *, percent_rank() over (partition by manager_id order by salary desc) as salary_percent_rank, lead(salary, 1, 0) over (partition by manager_id order by salary, id) as next_salary from deduped), with_dims as (select e.id, e.manager_id, e.salary_percent_rank, e.next_salary, p2.hire_date, p2.level, p2.email as employee_email from with_windows e inner join employees p2 on e.manager_id = p2.id), cleaned as (select *, case when level = 'L1' then 1 else 0 end as is_l1, coalesce(level, 'NONE') as level_filled from with_dims where hire_date > date '2023-04-14' and level is distinct from 'L2'), grouped as (select date_trunc('year', hire_date) as year_start, date_trunc('week', hire_date) as week_start, sort_array(collect_set(level)) as level_list, count(distinct manager_id) as distinct_manager_ids, round(sum(is_l1) / nullif(count(case when level = 'L2' then 1 end), 0), 2) as is_l1_per_l2, sum(case when level = 'L5' then is_l1 else 0 end) as l5_is_l1, count_if(level = 'L3') as l3_events from cleaned group by year_start, week_start) select year_start, week_start, level_list, distinct_manager_ids, is_l1_per_l2, l5_is_l1 from grouped;
